import { experimental_evaluate as evaluate } from "ai";
import {
  ClientProduct,
  ProductMatchResult,
  ProductMatchResultSchema,
  SupplierCandidate
} from "./types.js";

export interface IAiMatcherService {
  evaluateMatch(
    clientProduct: ClientProduct,
    candidate: SupplierCandidate
  ): Promise<ProductMatchResult>;
}

export class JevSystemOneMatcher implements IAiMatcherService {
  private readonly modelId: string;
  private readonly maxRetries: number;
  private readonly initialDelayMs: number;

  constructor(
    modelId: string,
    maxRetries: number = 3,
    initialDelayMs: number = 400
  ) {
    if (!modelId || modelId.trim() === "") {
      throw new Error("modelId es obligatorio para inicializar JevSystemOneMatcher");
    }
    this.modelId = modelId;
    this.maxRetries = maxRetries;
    this.initialDelayMs = initialDelayMs;
  }

  public async evaluateMatch(
    clientProduct: ClientProduct,
    candidate: SupplierCandidate
  ): Promise<ProductMatchResult> {
    const statePayload = JSON.stringify({
      clientProduct: {
        sku: clientProduct.sku,
        name: clientProduct.name
      },
      supplierCandidate: {
        sku: candidate.sku,
        name: candidate.name,
        lexicalSimilarityScore: candidate.similarityScore
      }
    });

    let attempt = 0;
    while (attempt < this.maxRetries) {
      try {
        const rawEvaluation = await evaluate({
          model: this.modelId,
          state: statePayload,
          questions: {
            isMatch: {
              type: "boolean",
              instructions: "Determina si ambos registros corresponden al mismo producto fisico y comercial exacto."
            },
            confidenceScore: {
              type: "number",
              instructions: "Nivel de certeza de la inferencia, escala 0.0 a 1.0."
            },
            matchType: {
              type: "string",
              instructions: "Clasifica exactamente: EXACT_CODE, EQUIVALENT_VARIANT o DIFFERENT_PRODUCT."
            },
            discrepancyReason: {
              type: "string",
              instructions: "Clasifica discrepancia exactamente: NONE, PACKAGING_DIFFERENCE, SPECIFICATION_MISMATCH, BRAND_MISMATCH, VARIANT_MISMATCH o NO_CANDIDATES_FOUND."
            }
          }
        });

        const evaluationPayload = this.extractEvaluationPayload(rawEvaluation);

        const sanitizedPayload = {
          isMatch: this.unwrapPrimitive(evaluationPayload.isMatch),
          confidenceScore: Number(this.unwrapPrimitive(evaluationPayload.confidenceScore)),
          matchType: String(this.unwrapPrimitive(evaluationPayload.matchType) ?? "").trim().toUpperCase(),
          discrepancyReason: String(this.unwrapPrimitive(evaluationPayload.discrepancyReason) ?? "").trim().toUpperCase()
        };

        const validation = ProductMatchResultSchema.safeParse(sanitizedPayload);
        if (!validation.success) {
          const formattedErrors = JSON.stringify(validation.error.issues, null, 2);
          throw new Error(
            `Contrato de tipos violado por la salida del evaluador: ${formattedErrors}. Raw output: ${JSON.stringify(rawEvaluation)}`
          );
        }

        return validation.data;
      } catch (error) {
        attempt++;
        if (attempt >= this.maxRetries) {
          throw new Error(
            `Fallo de inferencia Jev tras ${this.maxRetries} intentos: ${(error as Error).message}`
          );
        }
        const delay = this.initialDelayMs * Math.pow(2, attempt) + Math.random() * 10;
        await new Promise((res) => setTimeout(res, delay));
      }
    }

    throw new Error("Estado inalcanzable en evaluador Jev.");
  }

  private extractEvaluationPayload(raw: unknown): Record<string, unknown> {
    if (raw && typeof raw === "object") {
      if ("answers" in raw && typeof (raw as { answers: unknown }).answers === "object") {
        return (raw as { answers: Record<string, unknown> }).answers;
      }
      if ("results" in raw && typeof (raw as { results: unknown }).results === "object") {
        return (raw as { results: Record<string, unknown> }).results;
      }
      return raw as Record<string, unknown>;
    }
    return {};
  }

  private unwrapPrimitive(value: unknown): unknown {
    if (value && typeof value === "object" && !Array.isArray(value)) {
      const record = value as Record<string, unknown>;
      if ("answer" in record) return record.answer;
      if ("value" in record) return record.value;
    }
    return value;
  }
}